import{_ as a,o as t,c as r,a0 as n}from"./chunks/framework.jwovEGr5.js";const m=JSON.parse('{"title":"References and Bibliography","description":"","frontmatter":{},"headers":[],"relativePath":"frensense-paper/14_REFERENCES.md","filePath":"frensense-paper/14_REFERENCES.md"}'),o={name:"frensense-paper/14_REFERENCES.md"};function i(s,e,d,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="references-and-bibliography" tabindex="-1">References and Bibliography <a class="header-anchor" href="#references-and-bibliography" aria-label="Permalink to &quot;References and Bibliography&quot;">​</a></h1><p>This document lists all academic papers, datasets, and software libraries referenced in the Frensense system design.</p><hr><h2 id="core-algorithms" tabindex="-1">Core Algorithms <a class="header-anchor" href="#core-algorithms" aria-label="Permalink to &quot;Core Algorithms&quot;">​</a></h2><h3 id="locality-sensitive-hashing-and-minhash" tabindex="-1">Locality-Sensitive Hashing and MinHash <a class="header-anchor" href="#locality-sensitive-hashing-and-minhash" aria-label="Permalink to &quot;Locality-Sensitive Hashing and MinHash&quot;">​</a></h3><p><strong>Broder, A. Z. (1997)</strong><br> &quot;On the resemblance and containment of documents.&quot;<br><em>Proceedings of the Compression and Complexity of Sequences 1997 (SEQUENCES &#39;97)</em>, pp. 21–29. IEEE.<br> → Original MinHash paper. Proves <code>P[min(π(A)) = min(π(B))] = J(A, B)</code>.</p><p><strong>Indyk, P. and Motwani, R. (1998)</strong><br> &quot;Approximate nearest neighbors: towards removing the curse of dimensionality.&quot;<br><em>Proceedings of the 30th Annual ACM Symposium on Theory of Computing (STOC &#39;98)</em>, pp. 604–613.<br> → Foundational LSH theory: amplification via banding, S-curve analysis.</p><p><strong>Gionis, A., Indyk, P., and Motwani, R. (1999)</strong><br> &quot;Similarity search in high dimensions via hashing.&quot;<br><em>Proceedings of the 25th International Conference on Very Large Data Bases (VLDB &#39;99)</em>, pp. 518–529.<br> → Practical banded LSH implementation guidance.</p><h3 id="universal-hashing" tabindex="-1">Universal Hashing <a class="header-anchor" href="#universal-hashing" aria-label="Permalink to &quot;Universal Hashing&quot;">​</a></h3><p><strong>Dietzfelbinger, M., Karlin, A., Mehlhorn, K., Meyer auf der Heide, F., Rohnert, H., and Tarjan, R. E. (1997)</strong><br> &quot;A reliable randomized algorithm for the closest-pair problem.&quot;<br><em>Journal of Algorithms</em>, 25(1):19–51.<br> → Defines multiply-shift universal hash family: <code>h(x) = (a·x + b) mod 2^64</code> with odd <code>a</code>. Used in <code>minhash.rs</code>.</p><p><strong>Carter, J. L. and Wegman, M. N. (1979)</strong><br> &quot;Universal classes of hash functions.&quot;<br><em>Journal of Computer and System Sciences</em>, 18(2):143–154.<br> → Original universal hashing paper.</p><hr><h2 id="program-analysis" tabindex="-1">Program Analysis <a class="header-anchor" href="#program-analysis" aria-label="Permalink to &quot;Program Analysis&quot;">​</a></h2><h3 id="taint-analysis" tabindex="-1">Taint Analysis <a class="header-anchor" href="#taint-analysis" aria-label="Permalink to &quot;Taint Analysis&quot;">​</a></h3><p><strong>Newsome, J. and Song, D. (2005)</strong><br> &quot;Dynamic taint analysis for automatic detection, analysis, and signature generation of exploits on commodity software.&quot;<br><em>Proceedings of the 12th Annual Network and Distributed System Security Symposium (NDSS &#39;05)</em>.<br> → Defines dynamic taint tracking. Frensense&#39;s static taint analysis adapts the same source/sink/sanitizer model.</p><p><strong>Livshits, V. B. and Lam, M. S. (2005)</strong><br> &quot;Finding security vulnerabilities in Java applications with static analysis.&quot;<br><em>Proceedings of the 14th USENIX Security Symposium</em>, pp. 271–286.<br> → Static taint analysis for web application security. Closest paper to Frensense&#39;s intraprocedural taint model.</p><p><strong>Denning, D. E. (1976)</strong><br> &quot;A lattice model of secure information flow.&quot;<br><em>Communications of the ACM</em>, 19(5):236–243.<br> → Original information flow lattice. The <code>TaintRegistry</code> scope-stack is an instance of the Denning lattice with <code>Tainted &gt; Untainted</code> as the ordering.</p><h3 id="control-flow-analysis" tabindex="-1">Control Flow Analysis <a class="header-anchor" href="#control-flow-analysis" aria-label="Permalink to &quot;Control Flow Analysis&quot;">​</a></h3><p><strong>Allen, F. E. (1970)</strong><br> &quot;Control flow analysis.&quot;<br><em>SIGPLAN Notices</em>, 5(7):1–19.<br> → Original CFG construction paper. The <code>BasicBlock</code> and <code>CFEdgeKind</code> definitions are standard Allen-style.</p><p><strong>Cooper, K. D., Harvey, T. J., and Kennedy, K. (2001)</strong><br> &quot;A simple, fast dominance algorithm.&quot;<br><em>Software-Practice and Experience</em>, 4(1):1–10. Rice University Technical Report CS-06-33406.<br> → The iterative dominance algorithm used in <code>cfg/mod.rs::BasicBlock.dominators</code> computation.</p><h3 id="reaching-definitions-and-def-use-chains" tabindex="-1">Reaching Definitions and Def-Use Chains <a class="header-anchor" href="#reaching-definitions-and-def-use-chains" aria-label="Permalink to &quot;Reaching Definitions and Def-Use Chains&quot;">​</a></h3><p><strong>Aho, A. V., Lam, M. S., Sethi, R., and Ullman, J. D. (2006)</strong><br><em>Compilers: Principles, Techniques, and Tools</em> (2nd ed.).<br> Pearson Education.<br> → The &quot;Dragon Book.&quot; Reference for reaching definitions dataflow analysis (<code>cfg/def_use.rs</code>).</p><p><strong>Ryder, B. G. (1979)</strong><br> &quot;Constructing the call graph of a program.&quot;<br><em>IEEE Transactions on Software Engineering</em>, SE-5(3):216–226.<br> → Call graph construction. Frensense uses a simplified name-based approximation of this.</p><h3 id="tree-edit-distance" tabindex="-1">Tree Edit Distance <a class="header-anchor" href="#tree-edit-distance" aria-label="Permalink to &quot;Tree Edit Distance&quot;">​</a></h3><p><strong>Zhang, K. and Shasha, D. (1989)</strong><br> &quot;Simple fast algorithms for the editing distance between trees and related problems.&quot;<br><em>SIAM Journal on Computing</em>, 18(6):1245–1262.<br> → The Zhang-Shasha TED algorithm. <code>ast_distance.rs</code> implements a simplified variant on extracted skeletons.</p><h3 id="program-slicing" tabindex="-1">Program Slicing <a class="header-anchor" href="#program-slicing" aria-label="Permalink to &quot;Program Slicing&quot;">​</a></h3><p><strong>Weiser, M. (1984)</strong><br> &quot;Program slicing.&quot;<br><em>IEEE Transactions on Software Engineering</em>, SE-10(4):352–357.<br> → Original program slicing paper. <code>corpus/flow_fingerprint.rs</code> implements a lightweight non-PDG-based approximation of backward slicing.</p><h3 id="interprocedural-analysis" tabindex="-1">Interprocedural Analysis <a class="header-anchor" href="#interprocedural-analysis" aria-label="Permalink to &quot;Interprocedural Analysis&quot;">​</a></h3><p><strong>Grove, D., DeFouw, G., Dean, J., and Chambers, C. (1997)</strong><br> &quot;Call graph construction in object-oriented languages.&quot;<br><em>ACM SIGPLAN Notices</em>, 32(10):108–124.<br> → Call graph precision levels (CHA, RTA, etc.). Frensense operates at approximately the CHA precision level for its name-based call graph.</p><hr><h2 id="information-retrieval" tabindex="-1">Information Retrieval <a class="header-anchor" href="#information-retrieval" aria-label="Permalink to &quot;Information Retrieval&quot;">​</a></h2><h3 id="tf-idf" tabindex="-1">TF-IDF <a class="header-anchor" href="#tf-idf" aria-label="Permalink to &quot;TF-IDF&quot;">​</a></h3><p><strong>Sparck Jones, K. (1972)</strong><br> &quot;A statistical interpretation of term specificity and its application in retrieval.&quot;<br><em>Journal of Documentation</em>, 28(1):11–21.<br> → Original TF-IDF paper. The <code>compute_idf_weights()</code> function in <code>fingerprint/types.rs</code> implements this exactly.</p><h3 id="document-similarity-and-shingling" tabindex="-1">Document Similarity and Shingling <a class="header-anchor" href="#document-similarity-and-shingling" aria-label="Permalink to &quot;Document Similarity and Shingling&quot;">​</a></h3><p><strong>Broder, A. Z., Glassman, S. C., Manasse, M. S., and Zweig, G. (1997)</strong><br> &quot;Syntactic clustering of the Web.&quot;<br><em>Proceedings of the 6th International World Wide Web Conference (WWW &#39;97)</em>, pp. 391–404.<br> → W-shingling for document similarity. Frensense applies this to token sequences of function bodies.</p><hr><h2 id="machine-learning" tabindex="-1">Machine Learning <a class="header-anchor" href="#machine-learning" aria-label="Permalink to &quot;Machine Learning&quot;">​</a></h2><h3 id="contrastive-learning-and-metric-learning" tabindex="-1">Contrastive Learning and Metric Learning <a class="header-anchor" href="#contrastive-learning-and-metric-learning" aria-label="Permalink to &quot;Contrastive Learning and Metric Learning&quot;">​</a></h3><p><strong>Chopra, S., Hadsell, R., and LeCun, Y. (2005)</strong><br> &quot;Learning a similarity metric discriminatively, with application to face verification.&quot;<br><em>Proceedings of the 2005 IEEE Computer Society Conference on Computer Vision and Pattern Recognition (CVPR &#39;05)</em>, pp. 539–546.<br> → Contrastive loss. The (positive, negative) corpus pair training in Frensense maps to this framework.</p><p><strong>Schroff, F., Kalenichenko, D., and Philbin, J. (2015)</strong><br> &quot;FaceNet: A unified embedding for face recognition and clustering.&quot;<br><em>Proceedings of IEEE CVPR 2015</em>, pp. 815–823.<br> → Triplet loss. The contrastive scoring formula in <code>scorer.rs</code> is a direct analog of the triplet margin loss.</p><h3 id="probability-calibration" tabindex="-1">Probability Calibration <a class="header-anchor" href="#probability-calibration" aria-label="Permalink to &quot;Probability Calibration&quot;">​</a></h3><p><strong>Platt, J. C. (1999)</strong><br> &quot;Probabilistic outputs for support vector machines and comparisons to regularized likelihood methods.&quot;<br> In A. J. Smola, P. L. Bartlett, B. Schölkopf, and D. Schuurmans (Eds.), <em>Advances in Large Margin Classifiers</em>, pp. 61–74. MIT Press.<br> → Platt scaling (sigmoid calibration). The per-pattern calibration in <code>frensense-bundler/src/calibration.rs</code> implements this.</p><hr><h2 id="formal-methods" tabindex="-1">Formal Methods <a class="header-anchor" href="#formal-methods" aria-label="Permalink to &quot;Formal Methods&quot;">​</a></h2><h3 id="linear-temporal-logic" tabindex="-1">Linear Temporal Logic <a class="header-anchor" href="#linear-temporal-logic" aria-label="Permalink to &quot;Linear Temporal Logic&quot;">​</a></h3><p><strong>Pnueli, A. (1977)</strong><br> &quot;The temporal logic of programs.&quot;<br><em>Proceedings of the 18th Annual Symposium on Foundations of Computer Science (FOCS &#39;77)</em>, pp. 46–57. IEEE.<br> → Original LTL paper. The temporal property checker in <code>src/temporal/analyzer.rs</code> implements <code>G(A → F(B))</code> properties.</p><p><strong>Clarke, E. M. and Emerson, E. A. (1981)</strong><br> &quot;Design and synthesis of synchronization skeletons using branching time temporal logic.&quot;<br><em>Workshop on Logic of Programs</em>, LNCS 131, pp. 52–71. Springer.<br> → Model checking foundations.</p><hr><h2 id="datasets-and-corpora" tabindex="-1">Datasets and Corpora <a class="header-anchor" href="#datasets-and-corpora" aria-label="Permalink to &quot;Datasets and Corpora&quot;">​</a></h2><p><strong>Moonen, L., Vidziunas, L., and Bhandari, G. P. (2024)</strong><br> &quot;CVEfixes: Automated Collection of Vulnerabilities and Their Fixes from Open-Source Software&quot; (v1.0.8).<br><em>17th International Conference on Predictive Models and Data Analytics in Software Engineering (PROMISE)</em>, Athens, Greece. Zenodo.<br> DOI: <a href="https://doi.org/10.5281/zenodo.13138703" target="_blank" rel="noreferrer">https://doi.org/10.5281/zenodo.13138703</a><br> → Source of many corpus positive/negative pairs. CVE fix commits from open-source repositories.</p><p><strong>Semgrep, Inc. (2024)</strong><br><em>Semgrep Rules Repository</em>.<br> GitHub. <a href="https://github.com/semgrep/semgrep-rules" target="_blank" rel="noreferrer">https://github.com/semgrep/semgrep-rules</a><br> → Source of additional pattern inspiration. Frensense patterns are rewritten as concrete code example pairs rather than DSL rules.</p><p><strong>OWASP Foundation (2023)</strong><br><em>OWASP Juice Shop</em> (v15.x).<br> GitHub. <a href="https://github.com/juice-shop/juice-shop" target="_blank" rel="noreferrer">https://github.com/juice-shop/juice-shop</a><br> → Primary benchmark target. Intentionally vulnerable TypeScript/Node.js web application.</p><p><strong>OWASP Foundation (2023)</strong><br><em>OWASP NodeGoat</em>.<br> GitHub. <a href="https://github.com/OWASP/NodeGoat" target="_blank" rel="noreferrer">https://github.com/OWASP/NodeGoat</a><br> → Secondary benchmark target. Intentionally vulnerable Node.js/MongoDB application.</p><hr><h2 id="software-dependencies" tabindex="-1">Software Dependencies <a class="header-anchor" href="#software-dependencies" aria-label="Permalink to &quot;Software Dependencies&quot;">​</a></h2><p>Key libraries used in the implementation:</p><table tabindex="0"><thead><tr><th>Library</th><th>Version</th><th>Purpose</th></tr></thead><tbody><tr><td><code>tree-sitter</code></td><td>0.22</td><td>Parsing all supported languages</td></tr><tr><td><code>petgraph</code></td><td>0.6</td><td>Call graph (directed graph, BFS/DFS)</td></tr><tr><td><code>rayon</code></td><td>1.8</td><td>Data-parallel file and function analysis</td></tr><tr><td><code>rustc-hash</code> (<code>FxHashMap</code>)</td><td>1.1</td><td>Fast non-cryptographic hash maps</td></tr><tr><td><code>bincode</code></td><td>2.0</td><td>Binary serialization of bundle payloads</td></tr><tr><td><code>blake3</code></td><td>1.5</td><td>Cryptographic checksum for <code>.frc</code> bundles</td></tr><tr><td><code>oxc_*</code></td><td>0.14</td><td>JavaScript/TypeScript compiler (AST + module resolution)</td></tr><tr><td><code>serde</code> / <code>serde_json</code></td><td>1.0</td><td>JSON serialization (MCP, SARIF output)</td></tr><tr><td><code>lru</code></td><td>0.12</td><td><code>TaintCache</code> LRU eviction</td></tr><tr><td><code>walkdir</code></td><td>2.4</td><td>Recursive file system traversal</td></tr><tr><td><code>clap</code></td><td>4.4</td><td>CLI argument parsing</td></tr><tr><td><code>tracing</code></td><td>0.1</td><td>Structured logging (composition decisions, taint walks)</td></tr><tr><td><code>criterion</code></td><td>0.5</td><td>Benchmarking framework</td></tr></tbody></table>',57)])])}const g=a(o,[["render",i]]);export{m as __pageData,g as default};
